import { Image, type ImageProps } from 'expo-image';
import { StyleSheet } from 'react-native';
import { useStyles, useTheme } from '@/theme/ThemeProvider';
import type { Theme } from '@/theme/theme';

export type ImageRatio = keyof Theme['imageRatios'];

/**
 * Photos everywhere in the app:
 * - fixed crop ratio (cover 16:9, square 1:1, tile 4:3), so layouts never jump;
 * - a blurred placeholder while loading: either a blurhash string, or a tiny
 *   blurred image URL (Phase 4: generated by Cloudinary, no work for vendors);
 * - fades in, and is cached in memory and on disk.
 */
export function AppImage({
  uri,
  ratio = 'cover',
  placeholder,
  rounded = true,
  accessibilityLabel,
  style,
}: {
  uri: string | null | undefined;
  ratio?: ImageRatio;
  placeholder?: { blurhash: string } | { uri: string };
  rounded?: boolean;
  accessibilityLabel?: string;
  style?: ImageProps['style'];
}) {
  const theme = useTheme();
  const styles = useStyles(makeStyles);
  return (
    <Image
      source={uri ? { uri } : undefined}
      placeholder={placeholder as ImageProps['placeholder']}
      placeholderContentFit="cover"
      contentFit="cover"
      transition={{ duration: theme.motion.duration.normal, effect: 'cross-dissolve' }}
      cachePolicy="memory-disk"
      recyclingKey={uri ?? undefined}
      accessibilityLabel={accessibilityLabel}
      accessible={Boolean(accessibilityLabel)}
      style={[styles.image, { aspectRatio: theme.imageRatios[ratio] }, rounded && styles.rounded, style]}
    />
  );
}

const makeStyles = (theme: Theme) =>
  StyleSheet.create({
    image: { width: '100%', backgroundColor: theme.colors.surfaceMuted },
    rounded: { borderRadius: theme.radius.lg },
  });
